CREATE TABLE `platform_seed_runs` (`seed_key` VARCHAR(64) CHARACTER SET ascii NOT NULL,`status` ENUM('pending','completed') NOT NULL,`user_id` CHAR(36) CHARACTER SET ascii NULL,`email_hash` CHAR(64) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NULL,`created_at` DATETIME(3) NOT NULL,`completed_at` DATETIME(3) NULL,PRIMARY KEY(`seed_key`),UNIQUE KEY `uq_platform_seed_user`(`user_id`),CONSTRAINT `fk_platform_seed_user` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
